sys_variable_value.value:
(function execute(inputs, outputs) {
if (inputs.status_code == '200') {
    var responseObject = JSON.parse(inputs.response_body);
    var quoteUSD = parseFloat(responseObject.data.USD).toFixed(2);
    var inputReal = parseFloat(inputs.brazilian_real);

    var result = inputReal * quoteUSD;

    outputs.value_in_dollars = result.toFixed(2);
}
})(inputs, outputs);

